from rest_framework import viewsets, permissions
from rest_framework.versioning import NamespaceVersioning
from .models import FreightShipment
from .serializers import FreightShipmentSerializer

class FreightShipmentViewSet(viewsets.ModelViewSet):
    serializer_class = FreightShipmentSerializer
    permission_classes = [permissions.IsAuthenticated]
    versioning_class = NamespaceVersioning

    def get_queryset(self):
        return FreightShipment.objects.filter(
            carrier=self.request.user.carrier_profile,
            status__in=["IN_TRANSIT", "DISPATCHED"]
        )
